  mem.t = (mem.t || 0) + 1;
  if (mem.t % 12 === 0) mem.left = !mem.left;
  const move = s.dist > 700 ? "advance" : mem.left ? "strafeL" : "strafeR";
  return { move, attack: s.canShoot && s.aimOffset > 20 };
}

